package dbml_test

import (
	"strings"
	"testing"

	"github.com/stretchr/testify/require"

	"gitlab.com/udevs/dbdiagram/backend/pkg/dbml"
)

func export(t *testing.T, src string, d dbml.Dialect) string {
	t.Helper()

	out, err := dbml.ExportSQL(mustParse(t, src), d)
	require.NoError(t, err)

	return out
}

func TestExportPostgresGolden(t *testing.T) {
	want := `CREATE TYPE "post_status" AS ENUM ('draft', 'published');

CREATE TABLE "users" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "username" varchar NOT NULL UNIQUE,
  "email" varchar NOT NULL,
  "created_at" timestamp DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE TABLE "posts" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "title" varchar NOT NULL,
  "body" text,
  "user_id" integer NOT NULL,
  "status" "post_status",
  "created_at" timestamp,
  PRIMARY KEY ("id")
);

ALTER TABLE "posts" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");

COMMENT ON COLUMN "posts"."body" IS 'Content of the post';
`
	require.Equal(t, want, export(t, sample, dbml.Postgres))
}

func TestExportMySQLGolden(t *testing.T) {
	want := "CREATE TABLE `users` (\n" +
		"  `id` integer AUTO_INCREMENT,\n" +
		"  `username` varchar NOT NULL UNIQUE,\n" +
		"  `email` varchar NOT NULL,\n" +
		"  `created_at` timestamp DEFAULT now(),\n" +
		"  PRIMARY KEY (`id`)\n);\n\n" +
		"CREATE TABLE `posts` (\n" +
		"  `id` integer AUTO_INCREMENT,\n" +
		"  `title` varchar NOT NULL,\n" +
		"  `body` text COMMENT 'Content of the post',\n" +
		"  `user_id` integer NOT NULL,\n" +
		"  `status` ENUM('draft', 'published'),\n" +
		"  `created_at` timestamp,\n" +
		"  PRIMARY KEY (`id`)\n);\n\n" +
		"ALTER TABLE `posts` ADD FOREIGN KEY (`user_id`) REFERENCES `users` (`id`);\n"

	require.Equal(t, want, export(t, sample, dbml.MySQL))
}

func TestExportRelationsIndexesAndSchemas(t *testing.T) {
	src := "Table auth.u {\n a int [pk]\n b int\n c int\n indexes {\n  (b, c) [unique, name: 'bc']\n  `lower(b)` [type: hash]\n  (a, c) [pk]\n }\n Note: 'users'\n}\nTable v {\n a int [pk]\n u int\n}\nTable w {\n a int\n}\nRef: v.u > auth.u.a\nRef: auth.u.b < v.a\nRef: w.a - v.a\nRef: w.a <> v.a\n"
	out := export(t, src, dbml.Postgres)

	require.Contains(t, out, "CREATE SCHEMA IF NOT EXISTS \"auth\";")
	require.Contains(t, out, "CREATE TABLE \"auth\".\"u\" (")
	require.Contains(t, out, "PRIMARY KEY (\"a\", \"c\")", "the composite key from the pk index joins the column keys")
	require.Contains(t, out, "CREATE UNIQUE INDEX \"bc\" ON \"auth\".\"u\" (\"b\", \"c\");")
	require.Contains(t, out, "CREATE INDEX \"u_expr_idx\" ON \"auth\".\"u\" USING hash ((lower(b)));")
	require.Contains(t, out, "ALTER TABLE \"v\" ADD FOREIGN KEY (\"u\") REFERENCES \"auth\".\"u\" (\"a\");")
	require.Contains(t, out, "ALTER TABLE \"v\" ADD FOREIGN KEY (\"a\") REFERENCES \"auth\".\"u\" (\"b\");", "< puts the foreign key on the right-hand side")
	require.Contains(t, out, "ALTER TABLE \"w\" ADD FOREIGN KEY (\"a\") REFERENCES \"v\" (\"a\");")
	require.Contains(t, out, "-- many-to-many w.a <> v.a needs a junction table")
	require.Contains(t, out, "COMMENT ON TABLE \"auth\".\"u\" IS 'users';")
}

func TestExportWarnsInsteadOfSilentlyDropping(t *testing.T) {
	out := export(t, "Table t {\n a text [increment]\n b int [default: `1; drop table x`]\n}\n", dbml.Postgres)

	require.Contains(t, out, "-- t.a: increment ignored")
	require.Contains(t, out, "-- t.b: default left out")
	require.NotContains(t, out, "drop table")

	_, err := dbml.ExportSQL(mustParse(t, "Table t {\n a int\n}\n"), "oracle")
	require.Error(t, err)
	_, err = dbml.ExportSQL(nil, dbml.Postgres)
	require.Error(t, err)

	empty, err := dbml.ExportSQL(&dbml.Schema{}, dbml.Postgres)
	require.NoError(t, err)
	require.Empty(t, empty)
}

func TestExportEscapesHostileNames(t *testing.T) {
	src := "Table \"ta\\\"ble; -- x\" [note: 'n\\'; DROP TABLE y; --'] {\n" +
		" \"co`l\\\"; --\" text [default: 'a\\'b; -- c\\\\d', note: 'it\\'s; /* x */']\n" +
		"}\nEnum \"e';--\" {\n \"v';--\"\n}\n"
	s, errs := dbml.Parse(src)
	require.Empty(t, errs)

	pg, err := dbml.ExportSQL(s, dbml.Postgres)
	require.NoError(t, err)
	my, err := dbml.ExportSQL(s, dbml.MySQL)
	require.NoError(t, err)

	require.Contains(t, pg, `CREATE TABLE "ta""ble; -- x" (`)
	require.Contains(t, pg, "\"co`l\"\"; --\" text DEFAULT 'a''b; -- c\\d'")
	require.Contains(t, pg, `COMMENT ON TABLE "ta""ble; -- x" IS 'n''; DROP TABLE y; --';`)
	require.Contains(t, pg, `COMMENT ON COLUMN "ta""ble; -- x"."co`+"`"+`l""; --" IS 'it''s; /* x */';`)
	require.Contains(t, pg, `CREATE TYPE "e';--" AS ENUM ('v'';--');`)

	require.Contains(t, my, "CREATE TABLE `ta\"ble; -- x` (")
	require.Contains(t, my, "`co``l\"; --` text DEFAULT 'a''b; -- c\\\\d'", "MySQL doubles the backslash")
	require.Contains(t, my, "COMMENT='n''; DROP TABLE y; --'")

	for _, out := range []string{pg, my} {
		for _, line := range strings.Split(out, "\n") {
			if strings.HasPrefix(line, "--") {
				require.NotContains(t, line, "DROP", "a comment line must not carry user text")
			}
		}
	}
}

func TestExportQuotesUnsafeTypes(t *testing.T) {
	cases := map[string]string{
		"semicolon":    "Table t {\n a \"int); DROP TABLE x; --\"\n}\n",
		"comment":      "Table t {\n a \"int -- x\"\n}\n",
		"backslash":    "Table t {\n a enum('a\\\\')\n}\n",
		"unbalanced":   "Table t {\n a \"int)\"\n}\n",
		"hash comment": "Table t {\n a \"int # x\"\n}\n",
	}

	for name, src := range cases {
		t.Run(name, func(t *testing.T) {
			pg, my := export(t, src, dbml.Postgres), export(t, src, dbml.MySQL)

			// The text survives only as one quoted identifier, never as SQL.
			require.Contains(t, pg, `"a" "`)
			require.Contains(t, my, "`a` `")
			require.Contains(t, pg, "-- t.a: type written as a quoted name")
			require.Contains(t, my, "-- t.a: type written as a quoted name")
		})
	}

	ok := export(t, "Table t {\n a numeric(10,2)\n b \"double precision\"\n c int[]\n}\n", dbml.Postgres)
	require.Contains(t, ok, `"b" double precision`, "ordinary types pass through")
	require.Contains(t, ok, `"a" numeric(10,2)`)
	require.Contains(t, ok, `"c" int[]`)
}

func TestExportDropsUnsafeExpressions(t *testing.T) {
	cases := map[string]string{
		"statement":     "1; drop table x",
		"open quote":    "'x; y",
		"comment":       "1 /* x */",
		"line comment":  "1 -- x",
		"mysql comment": "1 # x",
	}

	for name, expr := range cases {
		t.Run(name, func(t *testing.T) {
			for _, d := range []dbml.Dialect{dbml.Postgres, dbml.MySQL} {
				out := export(t, "Table t {\n a int [default: `"+expr+"`]\n}\n", d)
				require.Contains(t, out, "-- t.a: default left out")
				require.NotContains(t, out, "DEFAULT")
				require.NotContains(t, out, "drop table")
			}

			idx := export(t, "Table t {\n a int\n indexes {\n  `"+expr+"`\n }\n}\n", dbml.Postgres)
			require.Contains(t, idx, "-- index on t left out")
			require.NotContains(t, idx, "CREATE INDEX")
		})
	}

	require.Contains(t, export(t, "Table t {\n a int [default: `now() + interval '1 day'`]\n}\n", dbml.Postgres), "DEFAULT now() + interval '1 day'")
}
